/** Nonces are generated by the proxy and forwarded to Next's renderer. */
export function contentSecurityPolicy({ production, nonce, supabaseUrl }: { production: boolean; nonce?: string; supabaseUrl?: string }): string {
  let https = "", sockets = "";
  try { const host = new URL(supabaseUrl ?? "").hostname; https = ` https://${host}`; sockets = ` wss://${host}`; } catch { /* No configured remote storage. */ }
  const scripts = nonce ? ` 'nonce-${nonce}' 'strict-dynamic'` : "";
  return [
    "default-src 'self'",
    `script-src 'self'${scripts}${production ? "" : " 'unsafe-inline' 'unsafe-eval'"} https://www.googletagmanager.com https://www.gstatic.com`,
    "style-src 'self' 'unsafe-inline'",
    `img-src 'self' data: blob: https://images.unsplash.com${https} https://*.google-analytics.com https://*.googletagmanager.com`,
    `media-src 'self' data: blob:${https}`,
    "font-src 'self' data:",
    `connect-src 'self' https://firebaseinstallations.googleapis.com https://firebase.googleapis.com https://fcm.googleapis.com https://fcmregistrations.googleapis.com https://*.google-analytics.com https://*.analytics.google.com https://*.googletagmanager.com${https}${sockets}`,
    "worker-src 'self' blob:", "object-src 'none'", "base-uri 'self'", "form-action 'self'", "frame-ancestors 'none'",
    ...(production ? ["upgrade-insecure-requests"] : []),
  ].join("; ");
}
